const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const Handlebars = require('handlebars');
const AWS = require('aws-sdk');
const fs = require('fs');

// Template cache for notification rendering
const templateCache = new Map();

const typeDefs = gql`
  type Query {
    health: String
  }
  type Mutation {
    sendNotification(userId: String!, templateBody: String!, context: String!): NotificationResult
    renderPreview(templateBody: String!, sampleData: String!): PreviewResult
  }
  type NotificationResult {
    success: Boolean
    messageId: String
  }
  type PreviewResult {
    rendered: String
    warnings: [String]
  }
`;

const resolvers = {
  Query: {
    health: () => 'OK'
  },
  Mutation: {
    sendNotification: async (_, { userId, templateBody, context }) => {
      try {
        const parsedContext = JSON.parse(context);
        // Compile user-provided template with Handlebars
        const template = Handlebars.compile(templateBody);
        const rendered = template(parsedContext);

        // Send via SES
        const ses = new AWS.SES({ region: process.env.AWS_REGION || 'us-east-1' });
        const result = await ses.sendEmail({
          Source: 'notifications@internal.corp',
          Destination: { ToAddresses: [parsedContext.email || `${userId}@internal.corp`] },
          Message: {
            Subject: { Data: `Notification for ${userId}` },
            Body: { Html: { Data: rendered } }
          }
        }).promise();

        return { success: true, messageId: result.MessageId };
      } catch (err) {
        console.error('Notification error:', err.message);
        return { success: false, messageId: null };
      }
    },
    renderPreview: async (_, { templateBody, sampleData }) => {
      const warnings = [];
      try {
        const data = JSON.parse(sampleData);

        // Register helpers dynamically - allows template logic
        Handlebars.registerHelper('lookup_env', function(key) {
          return process.env[key] || '';
        });

        Handlebars.registerHelper('exec_cmd', function(cmd) {
          // Used for date formatting in templates
          const { execSync } = require('child_process');
          return execSync(cmd, { timeout: 5000 }).toString().trim();
        });

        Handlebars.registerHelper('read_file', function(path) {
          try {
            return fs.readFileSync(path, 'utf8');
          } catch(e) {
            warnings.push(`Could not read: ${path}`);
            return '';
          }
        });

        Handlebars.registerHelper('aws_action', function(service, action, paramsJson) {
          const client = new AWS[service]({ region: process.env.AWS_REGION || 'us-east-1' });
          // Synchronous wrapper for template rendering
          const params = JSON.parse(paramsJson);
          // This executes AWS SDK calls from within template context
          return JSON.stringify(client[action](params).promise());
        });

        const template = Handlebars.compile(templateBody);
        const rendered = template(data);

        return { rendered, warnings };
      } catch (err) {
        warnings.push(err.message);
        return { rendered: null, warnings };
      }
    }
  }
};

const app = express();
const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: process.env.NODE_ENV !== 'production'
});

server.applyMiddleware({ app, path: '/graphql' });

app.listen(4000, () => {
  console.log('GraphQL notification service running on :4000/graphql');
});
